-- Reviewed owner-report links retain no bearer credentials and never authorize an unattended send.
CREATE TABLE tt_report_deliveries(id TEXT PRIMARY KEY,generation_id TEXT NOT NULL REFERENCES tt_report_generations(id),grant_id TEXT NOT NULL,identity_id TEXT NOT NULL,owner_id TEXT NOT NULL,property_id TEXT NOT NULL,recipient TEXT NOT NULL,snapshot TEXT NOT NULL,fingerprint TEXT NOT NULL,scope_fingerprint TEXT NOT NULL,prepared_by TEXT NOT NULL,prepared_at TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'prepared',version INTEGER NOT NULL DEFAULT 1,attempts INTEGER NOT NULL DEFAULT 0,provider_id TEXT,next_action TEXT NOT NULL,UNIQUE(generation_id,grant_id));
CREATE TRIGGER tt_report_delivery_fixed BEFORE UPDATE OF generation_id,grant_id,identity_id,owner_id,property_id,recipient,snapshot,fingerprint,scope_fingerprint,prepared_by,prepared_at ON tt_report_deliveries BEGIN SELECT RAISE(ABORT,'Report delivery evidence is immutable'); END;
CREATE TABLE tt_report_delivery_events(id TEXT PRIMARY KEY,delivery_id TEXT NOT NULL REFERENCES tt_report_deliveries(id),kind TEXT NOT NULL,reference TEXT NOT NULL,actor TEXT NOT NULL,at TEXT NOT NULL);
